using MailKit.Net.Smtp;
using MailKit.Security;
using MimeKit;
using TicketingService.Core.Interfaces.Services;

namespace TicketingService.Api.Services;

public class PortalEmailService(TenantAwareSmtpSender sender, ILogger<PortalEmailService> logger) : IPortalEmailService
{
    private static readonly string LogoBase64 = "";

    public async Task SendSubmissionConfirmationAsync(
        string toName,
        string toEmail,
        string subject,
        string type,
        string reference,
        string message,
        CancellationToken cancellationToken = default)
    {
        try
        {
            var typeLabel = type switch
            {
                "Complaint"      => "Complaint",
                "Feedback"       => "Feedback",
                "ProjectInquiry" => "Project Inquiry",
                _                => type, // allow callers to pass their own label
            };

            var html = BuildHtml(toName, subject, typeLabel, reference, message);
            await sender.SendAsync(toEmail, toName, $"[Lante] Submission Received — Ref: {reference}", html, logger);

            logger.LogInformation("Confirmation email sent to {Email} for reference {Reference}", toEmail, reference);
        }
        catch (Exception ex)
        {
            // Email failure must never break the submission — log and continue
            logger.LogError(ex, "Failed to send confirmation email to {Email}", toEmail);
        }
    }

    public async Task SendAcknowledgementAsync(
        string toName,
        string toEmail,
        string reference,
        string category,
        DateTime? resolutionDueAt,
        CancellationToken cancellationToken = default)
    {
        try
        {
            var dueLine = resolutionDueAt.HasValue
                ? $"<p style=\"margin:8px 0\">Target resolution: <strong>{resolutionDueAt.Value:dddd, dd MMM yyyy HH:mm} UTC</strong></p>"
                : "";
            var html = $@"<div style=""font-family:Arial,sans-serif;color:#111"">
                <p>Dear {System.Net.WebUtility.HtmlEncode(toName)},</p>
                <p>Thank you for contacting us. Your ticket has been logged and our team will attend to it.</p>
                <p style=""margin:8px 0"">Reference: <strong>{reference}</strong></p>
                <p style=""margin:8px 0"">Category: <strong>{System.Net.WebUtility.HtmlEncode(category)}</strong></p>
                {dueLine}
                <p>You can track progress using your reference number. Please quote it in any correspondence.</p>
                <p>Regards,<br/>Lante Support</p>
            </div>";

            await sender.SendAsync(toEmail, toName, $"[Lante] Ticket Received — Ref: {reference}", html, logger);

            logger.LogInformation("Acknowledgement email sent to {Email} for reference {Reference}", toEmail, reference);
        }
        catch (Exception ex)
        {
            logger.LogError(ex, "Failed to send acknowledgement email to {Email}", toEmail);
        }
    }

    public async Task SendAutoCloseWarningAsync(
        string toEmail,
        string subject,
        string reference,
        int hoursUntilClose,
        CancellationToken cancellationToken = default)
    {
        try
        {
            var html = $"""
                <!DOCTYPE html><html lang="en"><body style="font-family:Arial,sans-serif;color:#1f2937;">
                <div style="max-width:520px;margin:0 auto;padding:24px;">
                  <h2 style="color:#b45309;">We're waiting to hear from you</h2>
                  <p>Your request <strong>{subject}</strong> (reference <strong>{reference}</strong>) is on hold pending your response.</p>
                  <p>If we don't hear back within <strong>{hoursUntilClose} hours</strong>, it will be closed automatically. Just reply on the tracking page (reference <strong>{reference}</strong>) to keep it open.</p>
                  <p style="color:#6b7280;font-size:13px;">— Lante Support</p>
                </div></body></html>
                """;

            await sender.SendAsync(toEmail, toEmail, $"[Lante] Action needed — Ref: {reference}", html, logger);
            logger.LogInformation("Auto-close warning sent to {Email} for reference {Reference}", toEmail, reference);
        }
        catch (Exception ex)
        {
            logger.LogError(ex, "Failed to send auto-close warning to {Email}", toEmail);
        }
    }

    public async Task SendServiceRequestOtpAsync(
        string toName,
        string toEmail,
        string otpCode,
        string formTypeLabel,
        CancellationToken cancellationToken = default)
    {
        try
        {
            var html = BuildOtpHtml(toName, otpCode, formTypeLabel);
            await sender.SendAsync(toEmail, toName, $"[Lante] Your Verification Code — {otpCode}", html, logger);
            logger.LogInformation("OTP email sent to {Email}", toEmail);
        }
        catch (Exception ex) { logger.LogError(ex, "Failed to send OTP email to {Email}", toEmail); }
    }

    public async Task SendServiceRequestConfirmationAsync(
        string toName,
        string toEmail,
        string referenceNumber,
        string formTypeLabel,
        int    instrumentCount,
        string ticketReference,
        CancellationToken cancellationToken = default)
    {
        try
        {
            var html = BuildSrConfirmationHtml(toName, referenceNumber, formTypeLabel, instrumentCount, ticketReference);
            await sender.SendAsync(toEmail, toName, $"[Lante] Service Request Received — Ref: {referenceNumber}", html, logger);
            logger.LogInformation("SR confirmation sent to {Email} ref {Ref}", toEmail, referenceNumber);
        }
        catch (Exception ex) { logger.LogError(ex, "Failed to send SR confirmation to {Email}", toEmail); }
    }

    public async Task SendQuotationAsync(
        string toName,
        string toEmail,
        string referenceNumber,
        string quotationNumber,
        string formTypeLabel,
        IEnumerable<(string Description, decimal Quantity, decimal UnitPrice, decimal Amount)> lineItems,
        decimal subtotal,
        decimal vatRate,
        decimal vatAmount,
        decimal totalAmount,
        DateTime? validUntil,
        string? notes,
        string? clientOrganization  = null,
        string? clientAddress       = null,
        string? description         = null,
        CancellationToken cancellationToken = default)
    {
        try
        {
            var html = BuildQuotationHtml(toName, referenceNumber, quotationNumber, formTypeLabel,
                lineItems, subtotal, vatRate, vatAmount, totalAmount, validUntil, notes,
                clientOrganization, clientAddress, description);

            await sender.SendAsync(toEmail, toName, $"[Lante] Quotation {quotationNumber} — {formTypeLabel}", html, logger, cancellationToken);
            logger.LogInformation("Quotation {Quot} sent to {Email}", quotationNumber, toEmail);
        }
        catch (Exception ex) { logger.LogError(ex, "Failed to send quotation to {Email}", toEmail); }
    }

    public async Task SendAsync(
        IEnumerable<string> toEmails,
        string subject,
        string bodyHtml,
        CancellationToken cancellationToken = default)
    {
        var recipients = toEmails.Where(e => !string.IsNullOrWhiteSpace(e)).ToList();
        if (recipients.Count == 0) return;

        try
        {
            await sender.SendAsync(recipients, subject, bodyHtml, logger, cancellationToken);
            logger.LogInformation("Sent \"{Subject}\" to {Count} recipient(s)", subject, recipients.Count);
        }
        catch (Exception ex) { logger.LogError(ex, "Failed to send \"{Subject}\" to {Count} recipient(s)", subject, recipients.Count); }
    }

    private static string BuildQuotationHtml(
        string name, string refNumber, string quotNumber, string formTypeLabel,
        IEnumerable<(string Description, decimal Quantity, decimal UnitPrice, decimal Amount)> lineItems,
        decimal subtotal, decimal vatRate, decimal vatAmount, decimal totalAmount,
        DateTime? validUntil, string? notes,
        string? clientOrganization = null, string? clientAddress = null, string? description = null)
    {
        var escapedName = System.Net.WebUtility.HtmlEncode(name);
        var vatPct      = Math.Round(vatRate * 100).ToString("0");
        var validStr    = validUntil.HasValue ? validUntil.Value.ToString("dd MMM yyyy") : "30 days";
        var quoteDate   = DateTime.UtcNow.ToString("ddd, MMM dd, yyyy");
        var docRef      = $"QSL/QP/013- {quotNumber}";
        var billToName  = System.Net.WebUtility.HtmlEncode(
            !string.IsNullOrEmpty(clientOrganization) ? clientOrganization : name);
        var contactLine = !string.IsNullOrEmpty(clientOrganization)
            ? $"<p style='margin:0;font-size:13px;color:#374151;'>{escapedName}</p>" : "";
        var addressLine = !string.IsNullOrEmpty(clientAddress)
            ? $"<p style='margin:0;font-size:13px;color:#374151;'>{System.Net.WebUtility.HtmlEncode(clientAddress)}</p>" : "";
        var descHtml = !string.IsNullOrEmpty(description) ? $"""
            <p style="margin:0 0 4px;font-size:12px;color:#6b7280;">Description :</p>
            <p style="margin:0 0 20px;font-size:13px;color:#111827;">{System.Net.WebUtility.HtmlEncode(description)}</p>
            """ : "";

        var itemRows = string.Join("", lineItems.Select((li, i) =>
            $"""
            <tr style="border-top:1px solid #e5e7eb;">
              <td style="padding:8px 12px;font-size:13px;color:#374151;">{i + 1}</td>
              <td style="padding:8px 12px;font-size:13px;color:#111827;">{System.Net.WebUtility.HtmlEncode(li.Description)}</td>
              <td style="padding:8px 12px;font-size:13px;color:#374151;text-align:right;">{li.Quantity:0.##}</td>
              <td style="padding:8px 12px;font-size:13px;color:#374151;text-align:right;">{li.UnitPrice:N2}</td>
              <td style="padding:8px 12px;font-size:13px;color:#111827;font-weight:600;text-align:right;">{li.Amount:N2}</td>
            </tr>
            """));

        var notesHtml = string.IsNullOrEmpty(notes) ? "" : $"""
            <p style="margin:0 0 6px;font-size:13px;font-weight:600;color:#374151;">Notes</p>
            <p style="margin:0 0 20px;font-size:13px;color:#6b7280;line-height:1.6;">{System.Net.WebUtility.HtmlEncode(notes)}</p>
            """;

        return $"""
            <!DOCTYPE html>
            <html lang="en">
            <head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1.0"/></head>
            <body style="margin:0;padding:0;background:#f4f4f5;font-family:Arial,Helvetica,sans-serif;">
              <table width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f5;padding:32px 16px;">
                <tr><td align="center">
                  <table width="660" cellpadding="0" cellspacing="0" style="max-width:660px;width:100%;background:#ffffff;border-radius:4px;overflow:hidden;box-shadow:0 1px 4px rgba(0,0,0,.12);">

                    <!-- Header: logo left, QUOTE right -->
                    <tr><td style="padding:28px 32px 16px;">
                      <table width="100%" cellpadding="0" cellspacing="0">
                        <tr>
                          <td style="vertical-align:middle;">
                            <img src="data:image/png;base64,{LogoBase64}" alt="Qalibrated Systems" style="height:80px;width:auto;display:block;" />
                          </td>
                          <td style="vertical-align:top;text-align:right;">
                            <p style="margin:0;font-size:36px;font-weight:900;color:#1f2937;letter-spacing:2px;">QUOTE</p>
                            <p style="margin:0;font-size:13px;font-weight:600;color:#374151;">{docRef}</p>
                          </td>
                        </tr>
                      </table>
                    </td></tr>

                    <!-- Company address -->
                    <tr><td style="padding:0 32px 20px;">
                      <p style="margin:0 0 2px;font-size:13px;font-weight:700;color:#111827;">Inventing &amp; Making Happen</p>
                      <p style="margin:0;font-size:12px;color:#6b7280;line-height:1.7;">
                        P.O BOX 34463 - 00100, NAIROBI KENYA<br/>
                        PIN P051889248C<br/>
                        +254 714 999 996<br/>
                        accounts@qalibrated.co.ke | www.qalibrated.co.ke
                      </p>
                    </td></tr>

                    <!-- Bill To + Quote Date -->
                    <tr><td style="padding:0 32px 16px;">
                      <table width="100%" cellpadding="0" cellspacing="0">
                        <tr>
                          <td style="vertical-align:top;">
                            <p style="margin:0 0 4px;font-size:12px;color:#6b7280;">Bill To</p>
                            <p style="margin:0;font-size:14px;font-weight:700;color:#111827;">{billToName}</p>
                            {contactLine}
                            {addressLine}
                          </td>
                          <td style="vertical-align:top;text-align:right;white-space:nowrap;">
                            <p style="margin:0;font-size:13px;color:#374151;">Quote Date : &nbsp;<strong>{quoteDate}</strong></p>
                          </td>
                        </tr>
                      </table>
                    </td></tr>

                    <!-- Description -->
                    <tr><td style="padding:0 32px 12px;">
                      {descHtml}
                    </td></tr>

                    <!-- Line items -->
                    <tr><td style="padding:0 32px 8px;">
                      <table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #d1d5db;border-radius:4px;overflow:hidden;">
                        <tr style="background:#374151;">
                          <th style="padding:9px 12px;font-size:12px;font-weight:600;color:#ffffff;text-align:left;width:30px;">#</th>
                          <th style="padding:9px 12px;font-size:12px;font-weight:600;color:#ffffff;text-align:left;">Description</th>
                          <th style="padding:9px 12px;font-size:12px;font-weight:600;color:#ffffff;text-align:right;width:60px;">Qty</th>
                          <th style="padding:9px 12px;font-size:12px;font-weight:600;color:#ffffff;text-align:right;width:90px;">Rate</th>
                          <th style="padding:9px 12px;font-size:12px;font-weight:600;color:#ffffff;text-align:right;width:90px;">Amount</th>
                        </tr>
                        {itemRows}
                      </table>
                    </td></tr>

                    <!-- Totals -->
                    <tr><td style="padding:8px 32px 24px;">
                      <table style="margin-left:auto;" cellpadding="0" cellspacing="0" width="260">
                        <tr><td style="padding:5px 12px;font-size:13px;color:#6b7280;text-align:right;">Sub Total</td><td style="padding:5px 12px;font-size:13px;color:#111827;text-align:right;">{subtotal:N2}</td></tr>
                        <tr><td style="padding:5px 12px;font-size:13px;color:#6b7280;text-align:right;">General Rate ({vatPct}%)</td><td style="padding:5px 12px;font-size:13px;color:#111827;text-align:right;">{vatAmount:N2}</td></tr>
                        <tr style="border-top:1px solid #d1d5db;"><td style="padding:8px 12px;font-size:14px;font-weight:700;color:#111827;text-align:right;">Total</td><td style="padding:8px 12px;font-size:14px;font-weight:700;color:#111827;text-align:right;">KES{totalAmount:N2}</td></tr>
                      </table>
                    </td></tr>

                    <!-- Notes -->
                    <tr><td style="padding:0 32px 20px;">
                      {notesHtml}
                    </td></tr>

                    <!-- Terms & Conditions -->
                    <tr><td style="padding:0 32px 24px;border-top:1px solid #e5e7eb;">
                      <p style="margin:16px 0 6px;font-size:13px;font-weight:600;color:#374151;">Terms &amp; Conditions</p>
                      <p style="margin:0 0 4px;font-size:13px;color:#6b7280;">Dear valued customer</p>
                      <ol style="margin:6px 0 0;padding-left:18px;font-size:13px;color:#6b7280;line-height:1.8;">
                        <li>Sale of goods and services are subject to the standard terms and conditions of sale</li>
                        <li>All quoted prices are valid for {validStr}</li>
                        <li>Anything else noted to be defective as the work progresses shall be quoted for separately</li>
                      </ol>
                    </td></tr>

                    <!-- Footer -->
                    <tr><td style="background:#f9fafb;border-top:1px solid #e5e7eb;padding:14px 32px;text-align:center;">
                      <p style="margin:0;font-size:11px;color:#9ca3af;">Qalibrated Systems Limited, P.O BOX 34463 - 00100, NAIROBI, Kenya, +254 714 999 996</p>
                      <p style="margin:2px 0 0;font-size:11px;color:#9ca3af;">info@qalibrated.co.ke; www.qalibrated.co.ke &nbsp;&nbsp;|&nbsp;&nbsp; {quotNumber} - 1 of 1</p>
                    </td></tr>

                  </table>
                </td></tr>
              </table>
            </body>
            </html>
            """;
    }

    private static string BuildOtpHtml(string name, string otp, string formTypeLabel)
    {
        var escapedName = System.Net.WebUtility.HtmlEncode(name);
        return $"""
            <!DOCTYPE html>
            <html lang="en">
            <head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1.0"/></head>
            <body style="margin:0;padding:0;background:#f4f4f5;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;">
              <table width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f5;padding:32px 16px;">
                <tr><td align="center">
                  <table width="560" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,.08);">
                    <tr><td style="background:#0f1e45;padding:24px 32px;">
                      <div style="display:inline-block;width:32px;height:32px;background:#f59e0b;border-radius:7px;text-align:center;line-height:32px;font-weight:900;color:#fff;font-size:16px;margin-right:8px;vertical-align:middle;">L</div>
                      <span style="color:#fff;font-size:16px;font-weight:700;vertical-align:middle;">Lante</span>
                    </td></tr>
                    <tr><td style="padding:32px 32px 24px;">
                      <p style="margin:0 0 8px;font-size:20px;font-weight:700;color:#0f1e45;">Verify your email address</p>
                      <p style="margin:0;font-size:14px;color:#6b7280;line-height:1.6;">Hi {escapedName}, use the code below to confirm your {formTypeLabel} submission. The code expires in <strong>10 minutes</strong>.</p>
                    </td></tr>
                    <tr><td style="padding:0 32px 28px;text-align:center;">
                      <div style="display:inline-block;background:#fffbeb;border:2px solid #f59e0b;border-radius:12px;padding:20px 40px;">
                        <p style="margin:0 0 4px;font-size:11px;font-weight:600;color:#92400e;text-transform:uppercase;letter-spacing:.08em;">Verification Code</p>
                        <p style="margin:0;font-size:36px;font-weight:900;color:#0f1e45;font-family:'Courier New',monospace;letter-spacing:.25em;">{otp}</p>
                      </div>
                    </td></tr>
                    <tr><td style="padding:0 32px 32px;">
                      <p style="margin:0;font-size:13px;color:#9ca3af;text-align:center;">If you did not request this, please ignore this email. Do not share this code with anyone.</p>
                    </td></tr>
                    <tr><td style="background:#f9fafb;border-top:1px solid #e5e7eb;padding:16px 32px;text-align:center;">
                      <p style="margin:0;font-size:11px;color:#9ca3af;">Lante &copy; {DateTime.UtcNow.Year} &mdash; <a href="mailto:info@lante.co.ke" style="color:#f59e0b;text-decoration:none;">info@lante.co.ke</a></p>
                    </td></tr>
                  </table>
                </td></tr>
              </table>
            </body>
            </html>
            """;
    }

