    private static string BuildHtml(string name, string subject, string typeLabel, string reference, string message)
    {
        var escaped = System.Net.WebUtility.HtmlEncode(message);
        var escapedSubject = System.Net.WebUtility.HtmlEncode(subject);
        var escapedName = System.Net.WebUtility.HtmlEncode(name);

        return $"""
            <!DOCTYPE html>
            <html lang="en">
            <head>
              <meta charset="UTF-8" />
              <meta name="viewport" content="width=device-width, initial-scale=1.0" />
              <title>Submission Received</title>
            </head>
            <body style="margin:0;padding:0;background:#f4f4f5;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;">
              <table width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f5;padding:32px 16px;">
                <tr>
                  <td align="center">
                    <table width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,.08);">

                      <!-- Header -->
                      <tr>
                        <td style="background:#0f1e45;padding:28px 32px;">
                          <table width="100%" cellpadding="0" cellspacing="0">
                            <tr>
                              <td>
                                <div style="display:inline-block;width:36px;height:36px;background:#f59e0b;border-radius:8px;text-align:center;line-height:36px;font-weight:900;color:#fff;font-size:18px;margin-right:10px;vertical-align:middle;">L</div>
                                <span style="color:#ffffff;font-size:17px;font-weight:700;vertical-align:middle;">Lante</span>
                              </td>
                            </tr>
                          </table>
                        </td>
                      </tr>

                      <!-- Hero -->
                      <tr>
                        <td style="padding:32px 32px 24px;border-bottom:1px solid #f0f0f0;">
                          <p style="margin:0 0 8px;font-size:22px;font-weight:700;color:#0f1e45;">We've received your submission</p>
                          <p style="margin:0;font-size:15px;color:#6b7280;line-height:1.6;">
                            Thank you, {escapedName}. Your {typeLabel.ToLowerInvariant()} has been logged and our team will review it shortly.
                          </p>
                        </td>
                      </tr>

                      <!-- Reference block -->
                      <tr>
                        <td style="padding:24px 32px;">
                          <table width="100%" cellpadding="0" cellspacing="0" style="background:#fffbeb;border:1px solid #fcd34d;border-radius:10px;">
                            <tr>
                              <td style="padding:20px 24px;">
                                <p style="margin:0 0 4px;font-size:11px;font-weight:600;color:#92400e;text-transform:uppercase;letter-spacing:.05em;">Reference Number</p>
                                <p style="margin:0;font-size:26px;font-weight:800;color:#0f1e45;font-family:'Courier New',monospace;letter-spacing:.1em;">{reference}</p>
                                <p style="margin:8px 0 0;font-size:12px;color:#78716c;">Keep this number to track your submission status at any time.</p>
                              </td>
                            </tr>
                          </table>
                        </td>
                      </tr>

                      <!-- Submission details -->
                      <tr>
                        <td style="padding:0 32px 24px;">
                          <p style="margin:0 0 14px;font-size:13px;font-weight:600;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;">Submission Details</p>
                          <table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
                            <tr style="background:#f9fafb;">
                              <td style="padding:10px 16px;font-size:12px;font-weight:600;color:#6b7280;width:120px;">Type</td>
                              <td style="padding:10px 16px;font-size:14px;color:#111827;font-weight:600;">{typeLabel}</td>
                            </tr>
                            <tr style="border-top:1px solid #e5e7eb;">
                              <td style="padding:10px 16px;font-size:12px;font-weight:600;color:#6b7280;">Subject</td>
                              <td style="padding:10px 16px;font-size:14px;color:#111827;">{escapedSubject}</td>
                            </tr>
                            <tr style="background:#f9fafb;border-top:1px solid #e5e7eb;">
                              <td style="padding:10px 16px;font-size:12px;font-weight:600;color:#6b7280;vertical-align:top;">Message</td>
                              <td style="padding:10px 16px;font-size:14px;color:#374151;line-height:1.6;white-space:pre-wrap;">{escaped}</td>
                            </tr>
                          </table>
                        </td>
                      </tr>

                      <!-- CTA -->
                      <tr>
                        <td style="padding:0 32px 32px;text-align:center;">
                          <p style="margin:0 0 16px;font-size:14px;color:#6b7280;">You can check the status of your submission at any time using the reference number above.</p>
                          <a href="https://lante.africa/portal/track" style="display:inline-block;padding:12px 28px;background:#f59e0b;color:#ffffff;font-size:14px;font-weight:700;text-decoration:none;border-radius:8px;">
                            Track Your Submission →
                          </a>
                        </td>
                      </tr>

                      <!-- Footer -->
                      <tr>
                        <td style="background:#f9fafb;border-top:1px solid #e5e7eb;padding:20px 32px;text-align:center;">
                          <p style="margin:0;font-size:12px;color:#9ca3af;">
                            Lante &copy; {DateTime.UtcNow.Year} &mdash;
                            <a href="mailto:info@lante.co.ke" style="color:#f59e0b;text-decoration:none;">info@lante.co.ke</a>
                          </p>
                          <p style="margin:6px 0 0;font-size:11px;color:#d1d5db;">
                            This is an automated message. Please do not reply to this email.
                          </p>
                        </td>
                      </tr>

                    </table>
                  </td>
                </tr>
              </table>
            </body>
            </html>
            """;
    }
}
